[
  workspace: [
    root: "../..",
    project_globs: ["core/*", "runtime/*"]
  ],
  artifacts: [
    fixture_bundle: [
      roots: ["runtime/local"],
      package: [
        name: "fixture_bundle",
        otp_app: :fixture_bundle,
        version: "0.1.0",
        description: "Fixture bundle generated by weld",
        licenses: ["MIT"],
        links: %{"Source" => "https://example.test/fixture_bundle"},
        development_dependencies: [
          {:credo, "~> 1.7", only: [:dev, :test], runtime: false},
          {:dialyxir, "~> 1.4", only: [:dev, :test], runtime: false}
        ],
        docs: [
          source_url: "https://example.test/fixture_bundle",
          source_ref: "v0.1.0",
          extra_titles: %{"README.md" => "Overview"},
          groups_for_extras: [
            {"Start Here", ["README.md", "guides/getting_started.md"]},
            {"Reference", ["guides/architecture.md", "CHANGELOG.md"]}
          ]
        ]
      ],
      output: [
        docs: [
          "README.md",
          "CHANGELOG.md",
          "guides/architecture.md",
          "guides/getting_started.md"
        ]
      ],
      verify: [
        artifact_tests: ["packaging/weld/fixture_bundle/test"],
        smoke: [
          enabled: true,
          entry_file: "packaging/weld/fixture_bundle/smoke.ex"
        ]
      ]
    ]
  ]
]
